  "A50": {
    "id": "A50",
    "descriptor": "Zorlayıcı · Kod yazma",
    "prompt": "Linked list içinde döngü olup olmadığını slow/fast pointer yaklaşımıyla belirleyin. Ek bellek kullanan alternatifle karşılaştırın.",
    "solution": {
      "code": "class Node {\n    int value;\n    Node next;\n\n    Node(int value) {\n        this.value = value;\n    }\n}\n\n// Floyd: fast iki, slow bir adım ilerler; döngü varsa fast, slow'a döngü\n// içinde yetişir. Θ(n) zaman, Θ(1) ek bellek.\nstatic boolean hasCycle(Node head) {\n    Node slow = head;\n    Node fast = head;\n    while (fast != null && fast.next != null) {\n        slow = slow.next;\n        fast = fast.next.next;\n        if (slow == fast) return true;\n    }\n    return false;\n}\n\n// Alternatif: görülen düğümleri saklamak. Zaman yine Θ(n),\n// ama ek bellek Θ(n) olur.\nstatic boolean hasCycleWithSet(Node head) {\n    Set<Node> seen = new HashSet<>();\n    for (Node current = head; current != null; current = current.next) {\n        if (!seen.add(current)) return true;\n    }\n    return false;\n}",
      "language": "java"
    }
  },
